const vehicleHasOtherEBoarder = `-- name: VehicleHasOtherEBoarder :one
SELECT EXISTS (SELECT 1 FROM mobility_eboarder WHERE vehicle_id = $1 AND id <> $2)
`

type VehicleHasOtherEBoarderParams struct {
	VehicleID *uuid.UUID
	ID        uuid.UUID
}

func (q *Queries) VehicleHasOtherEBoarder(ctx context.Context, arg VehicleHasOtherEBoarderParams) (bool, error) {
	row := q.db.QueryRow(ctx, vehicleHasOtherEBoarder, arg.VehicleID, arg.ID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
